#include "rpg/startup_presentation.hpp"
#include <cmath>
#include <iostream>
#include <limits>
#include <stdexcept>
using namespace rpg::presentation;
void check(bool ok){if(!ok){throw std::runtime_error("Startup presentation contract failed");}}
bool near(double a,double b){return std::abs(a-b)<0.00001;}
template<class F>void invalid(F f){bool rejected=false;try{f();}catch(const std::invalid_argument&){rejected=true;}check(rejected);}
void landscape(){auto p=plan_video({1920,1080},{1280,720},Device::Desktop);check(near(p.content.width,1280) && near(p.content.height,720) && near(p.content.x,0) && p.request==Orientation::Keep && !p.use_side_art);}
void portrait_desktop(){auto p=plan_video({1080,1920},{1920,1080},Device::Desktop);check(near(p.content.width,607.5) && near(p.content.x,656.25) && near(p.content.height,1080) && p.use_side_art && near(p.left.width,656.25) && near(p.right.x,1263.75));}
void rotate(){auto p=plan_video({1920,1080},{1080,1920},Device::Mobile);check(p.request==Orientation::Landscape && near(p.content.height,607.5) && near(p.top.height,656.25));auto after=plan_video({1920,1080},{1920,1080},Device::Mobile);check(after.request==Orientation::Keep && near(after.content.height,1080));auto denied=plan_video({1920,1080},{1080,1920},Device::Mobile,false);check(denied.request==Orientation::Keep && near(denied.content.height,607.5));}
void portrait_mobile(){auto p=plan_video({1080,1920},{1080,1920},Device::Mobile);check(p.request==Orientation::Keep && near(p.content.width,1080) && !p.use_side_art);check(plan_video({1080,1920},{1920,1080},Device::Mobile).request==Orientation::Portrait);}
void hub_areas(){for(const auto area:{HubArea::Left,HubArea::Center,HubArea::Right}){auto p=plan_hub({3240,1920},{1080,1920},Device::Mobile,area);check(p.view==HubView::Focused && near(p.source_uv.width,1.0/3) && near(p.content.width,1080));double x=area==HubArea::Left?0:area==HubArea::Center?1.0/3:2.0/3;check(near(p.source_uv.x,x));}}
void hub_wide(){HubRegions custom;custom.center={0.25,0.1,0.5,0.8};auto region=plan_hub({4000,2000},{1000,1000},Device::Desktop,HubArea::Center,HubView::Focused,1.5,custom);check(near(region.source_uv.x,0.25) && near(region.content.height,800));auto p=plan_hub({3240,1920},{1920,1080},Device::Desktop);check(p.view==HubView::Panoramic && near(p.source_uv.width,1) && near(p.content.width,1822.5));auto focused=plan_hub({3240,1920},{1920,1080},Device::Desktop,HubArea::Center,HubView::Focused);check(focused.view==HubView::Focused && near(focused.content.width,607.5));check(plan_hub({3240,1920},{1200,1000},Device::Desktop).view==HubView::Focused);}
void resize(){auto a=plan_video({1080,1920},{1920,1080},Device::Desktop);auto b=plan_video({1080,1920},{1080,1920},Device::Desktop);check(a.use_side_art && !b.use_side_art && near(b.content.x,0));auto square=plan_video({100,100},{100,100},Device::Mobile);check(square.request==Orientation::Keep && near(square.content.width,100));}
void assets(){Variants v;check(!select_variant(v,Device::Mobile));v.desktop=Asset{"intro-pc","assets/video/intro.mp4",{1920,1080}};validate_asset(*v.desktop);check(select_variant(v,Device::Mobile)->id=="intro-pc");v.mobile=Asset{"intro-mobile","assets/video/intro-mobile.mp4",{1080,1920}};check(select_variant(v,Device::Mobile)->id=="intro-mobile" && select_variant(v,Device::Desktop)->id=="intro-pc");}
void paths(){for(const auto path:{"../x.png","C:/x.mp4","https://host/x","/x.png","assets//x.png","assets/../x.png","assets\\x.png","assets/x?.png","assets/a./x.png"}){check(!valid_asset_path(path));}check(valid_asset_path("assets/hub/panorama.png"));invalid([]{validate_asset({"x","../x",{1,1}});});}
void configuration(){validate_display({{1280,720},WindowMode::Windowed});validate_display({{1920,1080},WindowMode::Fullscreen});invalid([]{validate_display({{0,720},WindowMode::Windowed});});invalid([]{auto p=contain({0,1},{1,1});(void)p;});invalid([]{auto p=plan_hub({1,1},{1,1},Device::Desktop,HubArea::Center,HubView::Auto,std::numeric_limits<double>::quiet_NaN());(void)p;});}
int main(){try{landscape();portrait_desktop();rotate();portrait_mobile();hub_areas();hub_wide();resize();assets();paths();configuration();std::cout<<"STARTUP_PRESENTATION_TESTS_RESULT passed=10 total=10\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
